// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAttachmentPolicy Upload limits and allowed file extensions
	// (GET /attachment-policy)
	GetAttachmentPolicy(w http.ResponseWriter, r *http.Request)
	// UploadAttachment Upload one file
	// (POST /attachments)
	UploadAttachment(w http.ResponseWriter, r *http.Request)
	// DownloadAttachment Download a file on a ticket the user may see
	// (GET /attachments/{attachmentId})
	DownloadAttachment(w http.ResponseWriter, r *http.Request, attachmentId AttachmentId)
	// Login Sign in with email and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout Sign out and end the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe The signed-in user
	// (GET /auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ForgotPassword Email a password reset link
	// (POST /auth/password/forgot)
	ForgotPassword(w http.ResponseWriter, r *http.Request)
	// ResetPassword Set a new password with a reset token
	// (POST /auth/password/reset)
	ResetPassword(w http.ResponseWriter, r *http.Request)
	// GetBoard The agent board (staff)
	// (GET /board)
	GetBoard(w http.ResponseWriter, r *http.Request, params GetBoardParams)
	// GetBusinessHours The organisation's working hours
	// (GET /business-hours)
	GetBusinessHours(w http.ResponseWriter, r *http.Request)
	// UpdateBusinessHours Replace the working hours (admin only)
	// (PUT /business-hours)
	UpdateBusinessHours(w http.ResponseWriter, r *http.Request)
	// ListCatalogItems Every catalogue item, in display order (staff)
	// (GET /catalog-items)
	ListCatalogItems(w http.ResponseWriter, r *http.Request)
	// CreateCatalogItem Add a catalogue item (admin only)
	// (POST /catalog-items)
	CreateCatalogItem(w http.ResponseWriter, r *http.Request)
	// DeleteCatalogItem Delete a catalogue item no ticket uses (admin only)
	// (DELETE /catalog-items/{catalogItemId})
	DeleteCatalogItem(w http.ResponseWriter, r *http.Request, catalogItemId CatalogItemId)
	// UpdateCatalogItem Replace a catalogue item (admin only)
	// (PUT /catalog-items/{catalogItemId})
	UpdateCatalogItem(w http.ResponseWriter, r *http.Request, catalogItemId CatalogItemId)
	// ListClients Clients the user may see, by name
	// (GET /clients)
	ListClients(w http.ResponseWriter, r *http.Request)
	// CreateClient Add a client (admin only)
	// (POST /clients)
	CreateClient(w http.ResponseWriter, r *http.Request)
	// DeleteClient Delete a client with no requesters and no tickets (admin only)
	// (DELETE /clients/{clientId})
	DeleteClient(w http.ResponseWriter, r *http.Request, clientId ClientId)
	// GetClient One client
	// (GET /clients/{clientId})
	GetClient(w http.ResponseWriter, r *http.Request, clientId ClientId)
	// UpdateClient Replace a client's details (admin only)
	// (PUT /clients/{clientId})
	UpdateClient(w http.ResponseWriter, r *http.Request, clientId ClientId)
	// SetClientAgents Replace the agents assigned to a client (admin only)
	// (PUT /clients/{clientId}/agents)
	SetClientAgents(w http.ResponseWriter, r *http.Request, clientId ClientId)
	// ListClientAssignees Who can take a client's tickets
	// (GET /clients/{clientId}/assignees)
	ListClientAssignees(w http.ResponseWriter, r *http.Request, clientId ClientId)
	// ListClientRequesters A client's active and invited requesters, by name
	// (GET /clients/{clientId}/requesters)
	ListClientRequesters(w http.ResponseWriter, r *http.Request, clientId ClientId)
	// CreateClientRequester Add a requester to a client
	// (POST /clients/{clientId}/requesters)
	CreateClientRequester(w http.ResponseWriter, r *http.Request, clientId ClientId)
	// ListHolidayPresets Bundled official holiday lists (admin only)
	// (GET /holiday-presets)
	ListHolidayPresets(w http.ResponseWriter, r *http.Request)
	// LoadHolidayPreset Add a bundled year's missing holidays (admin only)
	// (POST /holiday-presets/{year}/load)
	LoadHolidayPreset(w http.ResponseWriter, r *http.Request, year int)
	// ListHolidays Holidays in date order
	// (GET /holidays)
	ListHolidays(w http.ResponseWriter, r *http.Request, params ListHolidaysParams)
	// CreateHoliday Add a holiday (admin only)
	// (POST /holidays)
	CreateHoliday(w http.ResponseWriter, r *http.Request)
	// DeleteHoliday Delete a holiday (admin only)
	// (DELETE /holidays/{holidayId})
	DeleteHoliday(w http.ResponseWriter, r *http.Request, holidayId openapi_types.UUID)
	// GetIntake What a report form offers for one client
	// (GET /intake)
	GetIntake(w http.ResponseWriter, r *http.Request, params GetIntakeParams)
	// GetNotificationSettings The user's notification switches and email timing
	// (GET /notification-settings)
	GetNotificationSettings(w http.ResponseWriter, r *http.Request)
	// SetEmailFrequency Choose when notification emails go out
	// (PUT /notification-settings/email-frequency)
	SetEmailFrequency(w http.ResponseWriter, r *http.Request)
	// SetNotificationPreference Switch one event's web and email notifications
	// (PUT /notification-settings/events/{event})
	SetNotificationPreference(w http.ResponseWriter, r *http.Request, event NotificationEvent)
	// ListNotifications The user's inbox, newest first
	// (GET /notifications)
	ListNotifications(w http.ResponseWriter, r *http.Request, params ListNotificationsParams)
	// MarkAllNotificationsRead Mark every inbox item read
	// (POST /notifications/read-all)
	MarkAllNotificationsRead(w http.ResponseWriter, r *http.Request)
	// GetUnreadNotificationCount How many inbox items are unread (the bell's count)
	// (GET /notifications/unread-count)
	GetUnreadNotificationCount(w http.ResponseWriter, r *http.Request)
	// SetNotificationRead Mark one inbox item read or unread
	// (PUT /notifications/{notificationId}/read)
	SetNotificationRead(w http.ResponseWriter, r *http.Request, notificationId NotificationId)
	// GetOrganization Public organisation branding for the sign-in page and footer
	// (GET /organization)
	GetOrganization(w http.ResponseWriter, r *http.Request)
	// ListPriorityLevels Priority names and descriptions, P1 to P4
	// (GET /priorities)
	ListPriorityLevels(w http.ResponseWriter, r *http.Request)
	// UpdatePriorityLevels Rename the priorities (admin only)
	// (PUT /priorities)
	UpdatePriorityLevels(w http.ResponseWriter, r *http.Request)
	// ListProjects Projects the user may see, by client and name
	// (GET /projects)
	ListProjects(w http.ResponseWriter, r *http.Request, params ListProjectsParams)
	// CreateProject Add a project (supervisors and admins)
	// (POST /projects)
	CreateProject(w http.ResponseWriter, r *http.Request)
	// DeleteProject Delete a project (supervisors and admins)
	// (DELETE /projects/{projectId})
	DeleteProject(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// GetProject One project
	// (GET /projects/{projectId})
	GetProject(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// UpdateProject Change a project's details (supervisors and admins)
	// (PUT /projects/{projectId})
	UpdateProject(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// UpdateProjectDod Replace a project's Definition of Done (supervisors and admins)
	// (PUT /projects/{projectId}/dod)
	UpdateProjectDod(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// UpdateProjectSla Replace a project's SLA targets and settings (supervisors and admins)
	// (PUT /projects/{projectId}/sla)
	UpdateProjectSla(w http.ResponseWriter, r *http.Request, projectId ProjectId)
	// ListTickets Tickets the user may see, newest first
	// (GET /tickets)
	ListTickets(w http.ResponseWriter, r *http.Request, params ListTicketsParams)
	// CreateTicket Open a ticket
	// (POST /tickets)
	CreateTicket(w http.ResponseWriter, r *http.Request)
	// GetTicket One ticket
	// (GET /tickets/{ticketKey})
	GetTicket(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// ListTicketActivity The ticket's activity log, oldest first (staff)
	// (GET /tickets/{ticketKey}/activity)
	ListTicketActivity(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// SetTicketAssignee Assign or unassign the ticket (staff)
	// (PUT /tickets/{ticketKey}/assignee)
	SetTicketAssignee(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// SetTicketDod Give the ticket its own Definition of Done, or return it to the project's (staff)
	// (PUT /tickets/{ticketKey}/dod)
	SetTicketDod(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// ListTicketMessages The ticket's conversation, oldest first
	// (GET /tickets/{ticketKey}/messages)
	ListTicketMessages(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// CreateTicketMessage Reply, or add an internal note (staff)
	// (POST /tickets/{ticketKey}/messages)
	CreateTicketMessage(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// SetTicketPriority Change the priority, with a reason (staff)
	// (PUT /tickets/{ticketKey}/priority)
	SetTicketPriority(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// ReopenTicket Reopen a resolved ticket while its reopen window lasts (client staff)
	// (POST /tickets/{ticketKey}/reopen)
	ReopenTicket(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// SetTicketStatus Move the ticket (staff)
	// (PUT /tickets/{ticketKey}/status)
	SetTicketStatus(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// AnswerTicketUat Approve or reject the fix while the ticket waits In UAT (client staff)
	// (POST /tickets/{ticketKey}/uat)
	AnswerTicketUat(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// ListTicketWatcherCandidates The client's other requesters who could follow the ticket (requesters)
	// (GET /tickets/{ticketKey}/watcher-candidates)
	ListTicketWatcherCandidates(w http.ResponseWriter, r *http.Request, ticketKey TicketKey, params ListTicketWatcherCandidatesParams)
	// ListTicketWatchers Colleagues following the ticket ("People notified", besides the requester)
	// (GET /tickets/{ticketKey}/watchers)
	ListTicketWatchers(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// AddTicketWatcher Add a colleague to the ticket (requesters)
	// (POST /tickets/{ticketKey}/watchers)
	AddTicketWatcher(w http.ResponseWriter, r *http.Request, ticketKey TicketKey)
	// RemoveTicketWatcher Take a colleague off the ticket (requesters)
	// (DELETE /tickets/{ticketKey}/watchers/{userId})
	RemoveTicketWatcher(w http.ResponseWriter, r *http.Request, ticketKey TicketKey, userId UserId)
	// ListUatRequests Tests waiting on the signed-in requester (client staff)
	// (GET /uat-requests)
	ListUatRequests(w http.ResponseWriter, r *http.Request)
	// ListUsers List all users (admin only)
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request)
}

